arguments.command:
cd /workspace && for t in BOM TRAILNL TRAILSPACE DEEP; do
case $t in
 BOM) printf '\xef\xbb\xbf{"version":2,"sessions":[]}' ;;
 TRAILNL) printf '{"version":2,"sessions":[]}\n' ;;
 TRAILSPACE) printf ' {"version":2,"sessions":[]} ' ;;
 DEEP) python3 -c "print('['*2000 + ']'*2000)" ;;
esac | python3 -B submission/main.py | head -c 100; echo " <= $t"; done
printf '{"version":2,"sessions":[]} \xff' | python3 -B submission/main.py; echo " <= BADUTF8"
